; Hi-res text map: The Secret of Monkey Island (UTE) Korean, with styled faces
; for the charsets the game draws in a styled font:
;   charset 4 (15 px) heavy serif display: intro and chapter cards, credits
;   charset 6 (14 px) light serif: the verb buttons
; Every other charset uses NanumGothic Bold. Latin letters and punctuation in
; the styled charsets come from a Latin face in the same style (range.); what
; that face lacks falls back to the charset's own faces.
;
; EB Garamond is a variable font; FreeType opens its default instance
; (Regular, 400). There is no weight key yet.
; See hires_text/fonts/FONTS.md for the licences.
[map]
version=2

[render]
scale=2
blend=auto

[fonts]
ko=data:hires_text/fonts/nanumgothic/NanumGothic-Bold.ttf
display_ko=data:hires_text/fonts/blackhansans/BlackHanSans-Regular.ttf
display_latin=data:hires_text/fonts/coustard/Coustard-Black.ttf
serif_ko=data:hires_text/fonts/nanummyeongjo/NanumMyeongjo-Bold.ttf
serif_latin=data:hires_text/fonts/ebgaramond/EBGaramond-VF.ttf

[font]
face=ko

[font.4]
face=display_ko, ko
range.basic-latin=display_latin
range.general-punctuation=display_latin, same

[font.6]
face=serif_ko, ko
range.basic-latin=serif_latin
range.general-punctuation=serif_latin, same
